fn sum_range(xs: List[Int], i: Int, j: Int) -> Int
  requires i >= 0 and j <= len(xs) and i <= j
  ensures (i == j and result == 0) or (i < j and result == xs[i] + sum_range(xs, i + 1, j))
  effects pure
  example sum_range([1, 2, 3], 0, 0) == 0
  example sum_range([1, 2, 3], 0, 2) == 3
  example sum_range([1, 2, 3], 1, 3) == 5
{
  if i == j then 0
  else if i == 0 then match xs {
    [] => 0
    [h, ..t] => h + sum_range(t, 0, j - 1)
  }
  else match xs {
    [] => 0
    [_, ..t] => sum_range(t, i - 1, j - 1)
  }
}

fn max_int(a: Int, b: Int) -> Int
  requires a >= 0 and b >= 0
  ensures (result == a or result == b) and result >= a and result >= b
  effects pure
  example max_int(3, 5) == 5
  example max_int(5, 3) == 5
{
  if a >= b then a else b
}

fn find_max_ending_helper(xs: List[Int], start: Int, end: Int, max_so_far: Int) -> Int
  requires start >= 0 and start < end
  ensures forall j in (start + 1)..((start + end) + 1): (sum_range(xs, start, j) <= result) or (j > len(xs))
  effects pure
  example find_max_ending_helper([1, 2, 3], 0, 1, 0) == 1
  example find_max_ending_helper([1, 2, 3], 0, 3, 0) == 6
